UPDATE folders SET message_count = (SELECT COUNT(*) FROM messages WHERE messages.folder_id = folders.id), unread_count = (SELECT COUNT(*) FROM messages WHERE messages.folder_id = folders.id AND messages.is_read = 0);
COMMIT;

-- Handbook visibility boundary: post-kickoff messages arrive through Stage mutations.
DELETE FROM attachments
WHERE message_id IN (SELECT id FROM messages WHERE date > '2026-10-05T19:30:00+08:00');
DELETE FROM sent_log
WHERE message_id IN (SELECT id FROM messages WHERE date > '2026-10-05T19:30:00+08:00');
DELETE FROM messages WHERE date > '2026-10-05T19:30:00+08:00';
UPDATE folders
SET message_count = (SELECT COUNT(*) FROM messages WHERE messages.folder_id = folders.id),
    unread_count = (SELECT COUNT(*) FROM messages WHERE messages.folder_id = folders.id AND is_read = 0);
